∀ {ffi : Type} {refs_ffi : store v × ffi_state ffi} {op : op} {vs : List v}
  {res : (store v × ffi_state ffi) × result v v},
  do_app refs_ffi op vs = some res → List.length refs_ffi.1 ≤ List.length res.1.1

∀ {m n v1 v2 : Type} [inst : BEq m] [inst_1 : BEq n] {R1 R2 : cml_id m n → v1 → v2 → Prop} {e1 : «namespace» m n v1}
  {e2 : «namespace» m n v2},
  (∀ (x : cml_id m n) (y : v1) (z : v2), R1 x y z → R2 x y z) → nsAll2 R1 e1 e2 → nsAll2 R2 e1 e2

∀ {m n v1 v2 : Type} [inst : BEq m] [inst_1 : BEq n] {R1 R2 : cml_id m n → v1 → v2 → Prop} {e1 : «namespace» m n v1}
  {e2 : «namespace» m n v2},
  (∀ (x : cml_id m n) (y : v1) (z : v2), R1 x y z → R2 x y z) → nsSub R1 e1 e2 → nsSub R2 e1 e2
